"use client";

import { type ReactNode, useState } from "react";
import { CalendarIcon } from "../icons/interface";
import { cx } from "../utils/cx";
import { Calendar, type DateRange } from "./calendar";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

type PickerBase = {
  /** Names the field when there is no visible label (or pass `id` and use `Field`). */
  "aria-label"?: string;
  id?: string;
  placeholder?: string;
  min?: Date;
  max?: Date;
  isDisabled?: (day: Date) => boolean;
  weekStartsOn?: 0 | 1;
  locale?: string;
  disabled?: boolean;
  className?: string;
  /** Format for the shown date. Default: a medium locale date. */
  format?: (date: Date) => string;
};

export type DatePickerProps = PickerBase & {
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (value: Date | null) => void;
};

export type DateRangePickerProps = PickerBase & {
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange) => void;
};

function Field({
  label,
  empty,
  disabled,
  className,
  ...rest
}: { label: ReactNode; empty: boolean; disabled?: boolean; className?: string } & Record<string, unknown>) {
  return (
    <PopoverTrigger asChild>
      <button
        type="button"
        {...rest}
        disabled={disabled}
        className={cx("hm-datepicker hm-control", className)}
        data-empty={empty ? "" : undefined}
      >
        <span className="hm-datepicker-label">{label}</span>
        <CalendarIcon size={14} strokeWidth={1.4} />
      </button>
    </PopoverTrigger>
  );
}

/** A field that opens a calendar in a popover. Picking a day closes it and returns focus to the field. */
export function DatePicker({
  value: controlled,
  defaultValue = null,
  onValueChange,
  placeholder = "Pick a date",
  format,
  min,
  max,
  isDisabled,
  weekStartsOn,
  locale,
  disabled,
  className,
  ...rest
}: DatePickerProps) {
  const [inner, setInner] = useState<Date | null>(defaultValue);
  const value = controlled === undefined ? inner : controlled;
  const [open, setOpen] = useState(false);
  const fmt = format ?? ((d: Date) => new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(d));
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Field
        {...rest}
        label={value ? fmt(value) : placeholder}
        empty={!value}
        disabled={disabled}
        className={className}
      />
      <PopoverContent aria-label="Choose a date" className="hm-datepicker-pop">
        <Calendar
          value={value}
          min={min}
          max={max}
          isDisabled={isDisabled}
          weekStartsOn={weekStartsOn}
          locale={locale}
          onValueChange={(d) => {
            if (controlled === undefined) setInner(d);
            onValueChange?.(d);
            setOpen(false);
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

/** Two dates in one field: the first press sets the start, the second the end, then it closes. */
export function DateRangePicker({
  value: controlled,
  defaultValue = {},
  onValueChange,
  placeholder = "Pick dates",
  format,
  min,
  max,
  isDisabled,
  weekStartsOn,
  locale,
  disabled,
  className,
  ...rest
}: DateRangePickerProps) {
  const [inner, setInner] = useState<DateRange>(defaultValue);
  const value = controlled ?? inner;
  const [open, setOpen] = useState(false);
  const fmt = format ?? ((d: Date) => new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(d));
  const label = value.from ? `${fmt(value.from)}${value.to ? ` – ${fmt(value.to)}` : " – …"}` : placeholder;
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <Field {...rest} label={label} empty={!value.from} disabled={disabled} className={className} />
      <PopoverContent aria-label="Choose dates" className="hm-datepicker-pop">
        <Calendar
          mode="range"
          value={value}
          min={min}
          max={max}
          isDisabled={isDisabled}
          weekStartsOn={weekStartsOn}
          locale={locale}
          onValueChange={(r) => {
            if (controlled === undefined) setInner(r);
            onValueChange?.(r);
            if (r.from && r.to) setOpen(false);
          }}
        />
      </PopoverContent>
    </Popover>
  );
}
